const n={ui:{fig:"Abb. 6",title:"Nahtverdeckter Reißverschluss",svgLabel:"Eine isometrische Zeichnung, wie man einen nahtverdeckten Reißverschluss in eine Naht einnäht: die Naht offen gelassen; der Reißverschluss geöffnet und seine Spirale von hinten mit einem kaum warmen Bügeleisen flach gebügelt; der Reißverschluss mit der rechten Seite nach unten auf der rechten Seite eines Teils, die Spirale auf der Nahtlinie, mit dem Nähfuß für nahtverdeckte Reißverschlüsse von oben nach unten genäht, bis der Fuß an den Schieber stößt; die andere Seite genauso, die Spirale in der anderen Rille, die Oberkanten aufeinander; der Reißverschluss geschlossen; die Naht darunter mit dem Reißverschlussfuß genäht; die Enden des Reißverschlussbands nur an die Nahtzugaben genäht. Von außen sieht man nur die Nahtlinie und den Schieber.",prev:"Vorheriger Schritt",dot:(e,i)=>e?`Schritt ${e}: ${i}`:i,start:"Schritte →",next:"Weiter →",overview:"Übersicht",stepOf:(e,i)=>`Schritt ${e} von ${i}`,machine:e=>`Maschine: ${e}`,inThisStep:"In diesem Schritt",takeApart:"Durch den Stoff sehen",putTogether:"Zurück zum Stoff",replay:"↻ Noch einmal",parts:"Teile",allSteps:"Schritt-für-Schritt-Anleitung",endView:"QUERSCHNITT"},stitches:{straight:"Geradstich"},labels:{seamOpen:"Naht offen lassen",zipperFirst:"zuerst der Reißverschluss",openZip:"Reißverschluss öffnen",fromBack:"Spirale von hinten flach bügeln",coolIron:"kaum warmes Bügeleisen",faceDown:"rechte Seite nach unten",coilOnSeam:"Spirale auf der Nahtlinie",oneGroove:"Spirale in einer Rille",topDown:"von oben nach unten",toPull:"bis der Fuß an den Schieber stößt",otherPiece:"das andere Teil, rechte Seite oben",freeHalf:"freie Hälfte, rechte Seite unten",topsLevel:"Oberkanten aufeinander",notTwisted:"nicht verdreht",otherGroove:"Spirale in der anderen Rille",close:"Reißverschluss schließen",rightSides:"rechts auf rechts",aboveSide:"etwas oberhalb, seitlich",zipperFoot:"Reißverschlussfuß",tapeEnds:"nur an die Nahtzugaben",rightUp:"rechte Seite nach oben",onlyPull:"nur Nahtlinie und Schieber"},steps:[{title:"Nahtverdeckter Reißverschluss",text:"Von außen sieht man den Reißverschluss nicht: nur die Nahtlinie und den Schieber. Tippe, um durch den Stoff zu sehen."},{title:"Naht offen lassen",text:"Lass die Naht offen: Zuerst wird der nahtverdeckte Reißverschluss eingenäht, danach die Naht darunter.",details:["Näh die Naht noch nicht: Der Reißverschluss kommt zuerst an die offenen Kanten.","Die Naht unter dem Reißverschluss nähst du, wenn der Reißverschluss drin ist."]},{title:"Spirale flach bügeln",text:"Öffne den Reißverschluss. Bügle die Spirale von hinten mit einem kaum warmen Bügeleisen flach.",details:["Nimm einen nahtverdeckten Reißverschluss, der etwas länger als der Schlitz ist.","Öffne den Reißverschluss ganz.","Dreh ihn auf die Rückseite und bügle die Spirale mit einem kaum warmen Bügeleisen flach: Ein heißes Bügeleisen schmilzt die Spirale."]},{title:"Rechte Seite nach unten",text:"Leg den geöffneten Reißverschluss mit der rechten Seite nach unten auf die rechte Seite eines Teils, die Spirale genau auf der Nahtlinie, und steck ihn fest.",details:["Leg eine Hälfte des geöffneten Reißverschlusses mit der rechten Seite nach unten auf die rechte Seite eines Teils.","Die Spirale liegt genau auf der Nahtlinie, das Band auf der Nahtzugabe.","Steck das Band fest."]},{title:"Die erste Seite",text:"Setz den Nähfuß für nahtverdeckte Reißverschlüsse ein, die Spirale in einer seiner Rillen. Näh von oben nach unten, bis der Fuß an den Schieber stößt, und verriegle.",details:["Setz den Nähfuß für nahtverdeckte Reißverschlüsse ein: Die Spirale läuft in einer der zwei Rillen darunter.","Näh von oben nach unten, dicht neben der Spirale, bis der Fuß an den Schieber stößt.","Verriegle dort.","Halte die Spirale in der Rille: Erfasst die Naht die Spirale, schließt der Reißverschluss nicht mehr."]},{title:"Die andere Seite",text:"Leg das andere Teil mit der rechten Seite nach oben hin und leg das erste Teil rechts auf rechts darauf, seine Nahtzugabe mit der angenähten Hälfte des Reißverschlusses zurückgeklappt. Die freie Hälfte des Reißverschlusses liegt mit der rechten Seite nach unten auf dem anderen Teil, die Spirale auf der Nahtlinie.",details:["Leg das andere Teil mit der rechten Seite nach oben hin.","Leg das erste Teil rechts auf rechts darauf, seine Nahtzugabe mit der angenähten Hälfte des Reißverschlusses zurückgeklappt.","Leg die freie Hälfte des Reißverschlusses mit der rechten Seite nach unten auf die rechte Seite des anderen Teils, die Spirale genau auf der Nahtlinie.","Leg die Oberkanten und eventuelle Quernähte aufeinander: Der Reißverschluss ist nicht verdreht. Steck ihn fest."]},{title:"Die andere Seite nähen",text:"Leg die Spirale in die andere Rille vom Nähfuß für nahtverdeckte Reißverschlüsse. Näh von oben nach unten, bis der Fuß an den Schieber stößt, und verriegle.",details:["Leg die Spirale in die andere Rille des Fußes.","Näh von oben nach unten, dicht neben der Spirale, bis der Fuß an den Schieber stößt.","Verriegle dort. Die Spirale bleibt aus der Naht."]},{title:"Reißverschluss schließen",text:"Schließe den Reißverschluss: Der Schieber kommt ganz nach oben.",details:["Schließe den Reißverschluss ganz.","Er gleitet leicht, wenn die Spirale nicht in der Naht steckt."]},{title:"Die Naht darunter",text:"Leg die Teile rechts auf rechts und wechsle zum Reißverschlussfuß. Näh die Naht unter dem Reißverschluss; beginne etwas oberhalb und seitlich vom Ende der Reißverschlussnaht.",details:["Leg die Teile rechts auf rechts, die Kanten bündig.","Wechsle zum normalen Reißverschlussfuß.","Beginne etwas oberhalb und seitlich vom Ende der Reißverschlussnaht und näh den Rest der Naht."]},{title:"Die Bandenden",text:"Klapp die Nahtzugaben auf und näh die Enden des Reißverschlussbands nur an die Nahtzugaben, nicht an die Teile.",details:["Klapp die Nahtzugaben auf.","Näh jedes Ende des Reißverschlussbands nur an seine eigene Nahtzugabe, nicht an das Teil."]},{title:"Rechte Seite nach oben",text:"Klapp die Teile auseinander und dreh sie auf die rechte Seite. Von außen sieht man nur die Nahtlinie und den Schieber.",details:["Klapp die Teile auseinander und dreh sie auf die rechte Seite.","Von außen sieht man nur die Nahtlinie und den Schieber."]}],legend:[{title:"Stoff",text:"zwei Teile, an der Nahtlinie verbunden · keine Naht sichtbar"},{title:"Nahtlinie",text:"die Spirale steckt darin · unter dem Reißverschluss eine normale Naht"},{title:"Reißverschluss",text:"unter dem Stoff · das Band nur an die Nahtzugaben genäht"},{title:"Schieber",text:"das Einzige, was man vom Reißverschluss sieht"}]};export{n as default};
